<script setup lang="ts">
import {ref,computed,watch} from 'vue';const props=defineProps<{value:any;data:any}>();const globalAdmin=computed(()=>!!props.value.judibas_administrator);const companySearch=ref(''),roleSearch=ref(''),taskSearch=ref('');
const primary=computed(()=>props.data.products.filter((p:any)=>p.workspace||props.value.product_slugs.includes(p.slug)).sort((a:any,b:any)=>['communication','projects','canteen'].indexOf(a.slug)-['communication','projects','canteen'].indexOf(b.slug)));
const other=computed(()=>props.data.products.filter((p:any)=>!primary.value.includes(p)));
watch(()=>[...props.value.company_ids,...props.value.product_slugs],()=>{props.value.canteen_level_ids||={};for(const id of Object.keys(props.value.canteen_level_ids))if(!props.value.company_ids.includes(Number(id))||!props.value.product_slugs.includes('canteen'))delete props.value.canteen_level_ids[id];},{immediate:true});
watch(()=>props.value.daymark_company_id,(value,old)=>{if(old!==undefined&&value!==old){props.value.daymark_department_id=null;props.value.daymark_custom_role_id=null;props.value.daymark_manager_ids=[];}});
if(props.value.daymark_active===undefined)props.value.daymark_active=true;
if(!props.value.daymark_role)props.value.daymark_role='employee';if(!props.value.daymark_manager_ids)props.value.daymark_manager_ids=[];
</script>
<template><div class="admin-access-fields">
<fieldset><legend>Assigned products <span>{{globalAdmin?'All products':value.product_slugs.length+' selected'}}</span></legend><p class="admin-field-help">{{globalAdmin?'Judibas Admin automatically manages every registered product, including future products.':'Choose the products this person can open.'}}</p><div v-if="!globalAdmin" class="admin-product-options"><label v-for="product in primary" :key="product.slug" :class="{selected:value.product_slugs.includes(product.slug)}"><input type="checkbox" v-model="value.product_slugs" :value="product.slug"><span><strong>{{product.name}}</strong><small>{{product.slug==='projects'?'Projects, tasks and team workflows':product.slug==='communication'?'Chats, communities and groups':product.category}}</small></span></label></div><details v-if="other.length&&!globalAdmin" class="admin-more-products"><summary>More products ({{other.length}})</summary><div class="admin-product-options"><label v-for="product in other" :key="product.slug"><input type="checkbox" v-model="value.product_slugs" :value="product.slug"><span>{{product.name}}</span></label></div></details></fieldset>
<fieldset><legend>Companies <span>{{value.company_ids.length}} selected</span></legend><p class="admin-field-help">{{globalAdmin?'Optional memberships for personal chats. Management covers all companies.':'Select one or more companies. Required for Communication, PMS, Canteen and Daymark.'}}</p><input v-if="data.companies.length>5" type="search" v-model="companySearch" aria-label="Find companies" placeholder="Find a company..."><div class="admin-access-options"><label class="check" v-for="company in data.companies.filter((c:any)=>c.name.toLowerCase().includes(companySearch.toLowerCase()))" :key="company.id"><input type="checkbox" v-model="value.company_ids" :value="company.id">{{company.name}}</label><p v-if="!data.companies.length" class="admin-field-help">No companies available.</p></div></fieldset>
<fieldset v-if="value.product_slugs.includes('communication')&&!globalAdmin"><legend>Communication access</legend><label class="check admin-switch"><input type="checkbox" v-model="value.communication_admin"><span><strong>Communication administrator</strong><small>Manage groups and invitations within assigned companies.</small></span></label><p class="admin-field-help">Other members can chat in their assigned companies and groups.</p><details v-if="value.group_ids" class="admin-optional"><summary>Groups <span>{{value.group_ids.length}} selected</span></summary><div class="admin-access-options"><label class="check" v-for="group in data.groups.filter((g:any)=>value.company_ids.includes(g.company_id))" :key="group.id"><input type="checkbox" v-model="value.group_ids" :value="group.id">{{group.name}}</label><p v-if="!data.groups.some((g:any)=>value.company_ids.includes(g.company_id))" class="admin-field-help">Select a company with groups to choose memberships.</p></div></details></fieldset>
<fieldset v-if="value.product_slugs.includes('canteen')&&!globalAdmin"><legend>Canteen access</legend><label>Canteen role<select v-model="value.canteen_role"><option value="employee">Employee</option><option value="admin">Canteen Admin</option><option value="kitchen">Kitchen</option><option value="cashier">Cashier</option></select></label><p class="admin-field-help">This role applies to selected companies. Choose a benefit level for each company below. Configure levels and item allowances inside Canteen.</p><div class="admin-access-columns"><label v-for="company in data.companies.filter((c:any)=>value.company_ids.includes(c.id))" :key="company.id">{{company.name}} benefit level<select v-model="value.canteen_level_ids[company.id]"><option :value="null">No level assigned</option><option v-for="level in (data.canteen_levels||[]).filter((l:any)=>l.company_id===company.id && (l.active || l.id===value.canteen_level_ids[company.id]))" :key="level.id" :value="level.id">{{level.name}}{{level.active?'':' (inactive)'}}</option></select><small class="admin-field-help" v-if="!(data.canteen_levels||[]).some((l:any)=>l.company_id===company.id && l.active)">Create benefit levels in this company's Canteen first.</small></label></div></fieldset><fieldset v-if="value.product_slugs.includes('projects')&&!globalAdmin"><legend>PMS access</legend><p class="admin-field-help">Select at least one role. Departments keep the existing PMS team structure.</p><div class="admin-access-columns"><div><strong>Roles</strong><input v-if="data.pms_roles.length>5" type="search" v-model="roleSearch" aria-label="Find PMS roles" placeholder="Find a role..."><div class="admin-access-options"><label class="check" v-for="role in data.pms_roles.filter((r:any)=>r.role_name.toLowerCase().includes(roleSearch.toLowerCase()))" :key="role.id"><input type="checkbox" v-model="value.pms_role_ids" :value="role.id">{{role.role_name}}</label></div></div><div><strong>Departments <small class="admin-field-help">optional</small></strong><div class="admin-access-options"><label class="check" v-for="department in data.pms_departments" :key="department.id"><input type="checkbox" v-model="value.pms_department_ids" :value="department.id">{{department.dept_name}}</label></div></div></div><details v-if="value.pms_task_ids" :open="value.pms_task_ids.length>0" class="admin-optional"><summary>Assign tasks <span>{{value.pms_task_ids.length}} selected</span></summary><p class="admin-field-help">Optional. Adds task and project membership when the invitation is accepted.</p><input type="search" v-model="taskSearch" aria-label="Find tasks" placeholder="Find a task..."><div class="admin-access-options"><label class="check" v-for="task in data.pms_tasks.filter((t:any)=>(!t.platform_company_id||value.company_ids.includes(t.platform_company_id))&&t.title.toLowerCase().includes(taskSearch.toLowerCase()))" :key="task.id"><input type="checkbox" v-model="value.pms_task_ids" :value="task.id">{{task.title}}</label></div></details></fieldset>
<fieldset v-if="value.product_slugs.includes('daymark')&&!globalAdmin"><legend>Daymark reporting access</legend><label class="check"><input type="checkbox" v-model="value.daymark_active">Daymark profile active</label><p class="admin-field-help">Daymark uses one reporting company per person. This does not change their access to other products.</p><div class="admin-access-columns"><label>Reporting company<select v-model.number="value.daymark_company_id" required><option :value="null">Select company</option><option v-for="c in data.companies.filter((c:any)=>value.company_ids.includes(c.id))" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Reporting role<select v-model="value.daymark_role"><option v-for="role in ['employee','pm','om','hr','ceo','md','company_admin']" :key="role" :value="role">{{({pm:'Project Manager',om:'Operations Manager',hr:'Human Resources',ceo:'CEO',md:'Managing Director',company_admin:'Company Admin',employee:'Employee'} as any)[role]}}</option></select></label><label>Department<select v-model.number="value.daymark_department_id"><option :value="null">Unassigned</option><option v-for="d in (data.daymark_departments||[]).filter((d:any)=>d.company_id===value.daymark_company_id)" :key="d.id" :value="d.id">{{d.name}}</option></select><small>Create departments under Administration / Daymark setup.</small></label><label>Designation<input v-model="value.daymark_designation" maxlength="200"></label><label>Custom role<select v-model.number="value.daymark_custom_role_id"><option :value="null">Use reporting role permissions</option><option v-for="role in (data.daymark_roles||[]).filter((r:any)=>r.company_id===value.daymark_company_id)" :key="role.id" :value="role.id">{{role.name}}</option></select></label><div><strong>Reporting managers</strong><label v-for="m in (data.daymark_managers||[]).filter((m:any)=>m.company_id===value.daymark_company_id&&m.id!==value.id)" :key="m.id" class="check"><input type="checkbox" v-model="value.daymark_manager_ids" :value="m.id">{{m.name}}</label></div></div></fieldset></div></template>
